function chooseEachTokenDestination(game, player, card, spec = {}, finishSpell = false, remaining = null, playedTokenIds = []) {
  const total = tokenCountFromSpec(game, player, spec);
  if (total <= 0) return false;
  const tokensRemaining = remaining ?? total;
  const options = preferHiddenDestinationOptions(game, card, [
    { id: "base", label: `${player.name}'s base`, cardId: "base" },
    ...game.battlefields.filter((field) => field.controlledBy === player.id).map(battlefieldOption)
  ]);
  const choice = {
    id: `choice-${Date.now()}-${Math.random()}`,
    playerId: player.id,
    card,
    effect: "playUnitTokenDestination",
    prompt: `Choose where to play token ${Math.max(1, total - tokensRemaining + 1)} of ${total} for ${card.name}.`,
    options,
    data: { spec: structuredClone(spec), remaining: tokensRemaining, playedTokenIds: structuredClone(playedTokenIds) },
    finishSpell,
    optional: false,
    fromShowdownChain: game.phase === "showdown"
  };
  if (!game.interactive) {
    applyAutomaticChoiceEffect(game, choice, options[0], "payment-choice-default");
    return Boolean(game.pendingChoice);
  }
  game.pendingChoice = choice;
  return true;
}

function chooseSaveFriendlyUnitThisTurn(game, player, card, spec = {}, finishSpell = false) {
  const options = allUnits(game)
    .filter((unit) => unit.controllerId === player.id)
    .map(cardOption);
  return promptChoice(game, player, card, {
    effect: "saveFriendlyUnitThisTurn",
    prompt: `Choose a friendly unit for ${card.name}.`,
    options,
    optional: true,
    finishSpell,
    data: { domain: spec.domain || null }
  });
}

function chooseTrashUnitToPlay(game, player, card, spec = {}, finishSpell = false) {
  const ignoresAllCosts = Boolean(spec.ignoreCost || spec.ignorePowerCost);
  const options = player.trash
    .filter((candidate) => candidate.type === "unit")
    .filter((candidate) => spec.maxEnergy == null || (candidate.energy || 0) <= spec.maxEnergy)
    .filter((candidate) => spec.maxPower == null || totalPowerAmount(candidate.power || []) <= spec.maxPower)
    .filter((candidate) => ignoresAllCosts
      || (spec.payCosts
        ? canPayReducedEnergyCard(game, player, candidate, 0)
        : payPowerRequirements(game, player,
          normalizeCardPowerRequirements(candidate, candidate.power || []), true, candidate)))
    .map(cardOption);
  return promptChoice(game, player, card, {
    effect: "playTrashUnit",
    prompt: `Choose a unit in your trash to play for ${card.name}.`,
    options,
    optional: true,
    finishSpell,
    data: {
      ignoreAllCosts: ignoresAllCosts,
      payCosts: Boolean(spec.payCosts),
      destination: spec.destination ?? null
    }
  });
}

function chooseTrashUnitToHand(game, player, card, spec = {}, finishSpell = false) {
  const cardType = spec.cardType || "unit";
  const options = player.trash
    .filter((candidate) => cardHasType(candidate, cardType))
    .filter((candidate) => spec.maxEnergy == null || (candidate.energy || 0) <= spec.maxEnergy)
    .map(cardOption);
  return promptChoice(game, player, card, {
    effect: "returnTrashUnitToHand",
    prompt: `Choose a ${cardType} in your trash to return for ${card.name}.`,
    options,
    optional: Boolean(spec.optional),
    finishSpell,
    data: { cardType }
  });
}

function chooseOpponentHandDiscard(game, player, card, spec = {}, finishSpell = false) {
  const declared = consumeDeclaredPlayTarget(card, "discardOpponent", game.players
    .filter((candidate) => candidate.id !== player.id)
    .map((candidate) => ({ id: candidate.id, label: candidate.name, cardId: candidate.id })));
  const opponent = game.players.find((candidate) =>
    candidate.id === declared?.declaration?.targetId && candidate.id !== player.id)
    || (!declared
      ? game.players.find((candidate) => candidate.id !== player.id)
      : null);
  const options = (opponent?.hand || [])
    .filter((candidate) => !spec.nonUnitOnly || candidate.type !== "unit")
    .map(cardOption);
  if (opponent) revealPrivateInfoForTurn(game, player.id, opponent.id, card);
  return promptChoice(game, player, card, {
    effect: "discardOpponentHand",
    prompt: `Choose a card from ${opponent?.name || "opponent"}'s hand for ${card.name}.`,
    options,
    optional: Boolean(spec.optional),
    finishSpell,
    data: { opponentId: opponent?.id || null }
  });
}

function chooseTideturnerSwap(game, player, card, spec) {
  const units = allUnits(game)
    .filter((unit) => unit.controllerId === player.id && unit.instanceId !== card.instanceId)
    .filter((unit) => !(spec.differentLocation || spec.requiresDifferentLocation)
      || unitsHaveDifferentLocations(game, card, unit));
  return promptChoice(game, player, card, {
    effect: "tideturnerSwap",
    prompt: `Choose a unit to swap with ${card.name}.`,
    options: units.map(cardOption),
    optional: Boolean(spec.optional),
    data: { attachEquipmentFromTarget: Boolean(spec.attachEquipmentFromTarget) }
  });
}

function unitsHaveDifferentLocations(game, first, second) {
  const firstLocation = findUnitLocation(game, first?.instanceId);
  const secondLocation = findUnitLocation(game, second?.instanceId);
  if (!firstLocation || !secondLocation) return false;
  if (firstLocation.type !== secondLocation.type) return true;
  if (firstLocation.type === "battlefield") {
    return firstLocation.battlefield.instanceId !== secondLocation.battlefield.instanceId;
  }
  return firstLocation.player.id !== secondLocation.player.id;
}

function chooseForgeAttachGear(game, player, card) {
  const gears = allGear(game).filter((gear) => gear.controllerId === player.id && gear.tags?.includes("Equipment"));
  return promptChoice(game, player, card, {
    effect: "forgeAttachGear",
    prompt: `Choose an Equipment to attach with ${card.name}.`,
    options: gears.map(cardOption),
    optional: true
  });
}

function promptChoice(game, player, card, config) {
  const deflectPaidTargetIds = [...new Set([
    ...(config.deflectPaidTargetIds || []),
    ...((config.data || {}).deflectPaidTargetIds || []),
    ...(card.deflectPaidTargetIds || [])
  ])];
  const choice = {
    id: `choice-${Date.now()}-${Math.random()}`,
    playerId: player.id,
    card,
    effect: config.effect,
    prompt: config.prompt,
    options: config.options,
    deflectPaidTargetIds,
    data: {
      ...(config.data || {}),
      deflectPaidTargetIds
    },
    finishSpell: Boolean(config.finishSpell),
    optional: Boolean(config.optional),
    fromShowdownChain: game.resolvingChainContext === "showdown"
      || (game.phase === "showdown" && Boolean(config.finishSpell)),
    fromActionChain: game.resolvingChainContext === "action"
  };

  const declaredTarget = consumeDeclaredPlayTarget(card, choice.effect, choice.options);
  if (declaredTarget) {
    if (!declaredTarget.option) {
      log(game, `${card.name}'s declared target is no longer legal.`);
      applyChoiceEffect(game, choice, {
        id: "mistargeted",
        label: "Declared target is no longer legal",
        cardId: null,
        declaredTargetId: declaredTarget.declaration?.targetId || null,
        mistargeted: true
      }, "declared-mistarget");
      return Boolean(game.pendingChoice || game.pendingPayment);
    }
    applyChoiceEffect(game, choice, declaredTarget.option, "declared-target");
    return Boolean(game.pendingChoice || game.pendingPayment);
  }

  if (!choice.options.length) {
    if (choice.optional) {
      log(game, `${card.name} has no valid target.`);
      if (choice.finishSpell) finishSpell(game, player, card);
      return false;
    }
    log(game, `${card.name} finds no valid target.`);
    if (choice.finishSpell) finishSpell(game, player, card);
    return false;
  }

  const declaredChoice = consumeDeclaredPlayChoice(card, choice.effect, choice.options);
  if (declaredChoice) {
    if (declaredChoice.declaration.optionId === "skip") {
      if (choice.optional) applyChoiceEffect(game, choice, { id: "skip", label: "Skip", cardId: null }, "declared-choice");
      return Boolean(game.pendingChoice);
    }
    if (!declaredChoice.option) {
      log(game, `${card.name}'s declared choice is no longer legal.`);
      if (choice.finishSpell) finishSpell(game, player, card);
      return false;
    }
    applyChoiceEffect(game, choice, declaredChoice.option, "declared-choice");
    return Boolean(game.pendingChoice);
  }

  if (!game.interactive) {
    applyAutomaticChoiceEffect(game, choice, choice.options[0], "prepared-choice-default");
    return false;
  }

  setPendingChoice(game, choice);
  log(game, `${player.name} chooses an effect target for ${card.name}.`);
  return true;
}

function setPendingChoice(game, choice) {
  if (game.decisionSafety) {
    game.decisionSafety.presentedChoices += 1;
    const enabledOptions = (choice?.options || []).filter((option) => !option?.disabled);
    if (!choice?.playerId || !choice?.effect || (!enabledOptions.length && !choice?.optional)) {
      game.decisionSafety.violations.push({
        kind: "invalid-pending-choice",
        effect: choice?.effect || null,
        playerId: choice?.playerId || null,
        enabledOptions: enabledOptions.length
      });
    }
    const optionIds = enabledOptions.map((option) => option?.id ?? option?.value ?? option);
    if (new Set(optionIds).size !== optionIds.length) {
      game.decisionSafety.violations.push({
        kind: "duplicate-choice-option",
        effect: choice?.effect || null,
        playerId: choice?.playerId || null
      });
    }
  }
  game.pendingChoice = choice;
  return true;
}

function applyAutomaticChoiceEffect(game, choice, option, reason = "non-interactive-default") {
  if (game.interactive) {
    if (game.decisionSafety) {
      game.decisionSafety.preventedAutomaticChoices += 1;
      game.decisionSafety.violations.push({
        kind: "automatic-choice-prevented",
        effect: choice?.effect || null,
        playerId: choice?.playerId || null,
        reason
      });
    }
    return setPendingChoice(game, choice);
  }
  applyChoiceEffect(game, choice, option, "automatic");
  return true;
}

function presentPreparedChoice(game, choice) {
  const declaredTarget = consumeDeclaredPlayTarget(choice.card, choice.effect, choice.options);
  if (declaredTarget) {
    applyChoiceEffect(game, choice, declaredTarget.option || {
      id: "mistargeted",
      label: "Declared target is no longer legal",
      cardId: null,
      declaredTargetId: declaredTarget.declaration?.targetId || null,
      mistargeted: true
    }, declaredTarget.option ? "declared-target" : "declared-mistarget");
    return true;
  }
  const declaredChoice = consumeDeclaredPlayChoice(choice.card, choice.effect, choice.options);
  if (declaredChoice) {
    if (declaredChoice.declaration.optionId === "skip") return true;
    if (!declaredChoice.option) return false;
    applyChoiceEffect(game, choice, declaredChoice.option, "declared-choice");
    return true;
  }
  if (!game.interactive) {
    applyAutomaticChoiceEffect(game, choice, choice.options[0], "presented-choice-default");
    return true;
  }
  return setPendingChoice(game, choice);
}

function resolveDeclaredPreparedChoice(game, choice) {
  const declaredTarget = consumeDeclaredPlayTarget(choice.card, choice.effect, choice.options);
  if (declaredTarget) {
    applyChoiceEffect(game, choice, declaredTarget.option || {
      id: "mistargeted",
      label: "Declared target is no longer legal",
      cardId: null,
      declaredTargetId: declaredTarget.declaration?.targetId || null,
      mistargeted: true
    }, declaredTarget.option ? "declared-target" : "declared-mistarget");
    return true;
  }
  const declaredChoice = consumeDeclaredPlayChoice(choice.card, choice.effect, choice.options);
  if (!declaredChoice) return false;
  const option = declaredChoice.declaration.optionId === "skip"
    ? choice.options.find((candidate) => candidate.id === "skip")
      || { id: "skip", label: "Skip", cardId: null }
    : declaredChoice.option;
  applyChoiceEffect(game, choice, option || {
    id: "mistargeted",
    label: "Declared choice is no longer legal",
    cardId: null,
    mistargeted: true
  }, option ? "declared-choice" : "declared-mistarget");
  return true;
}

